26	 */
27	@Service
28	public class ReleaseService {
29	
30	    /** 单批最大条数。 */
31	    static final int MAX_BATCH_SIZE = 50;
32	
33	    private final MeasurementRepository measurements;
34	    private final CertificateRepository certificates;
35	    private final ReleaseRepository releases;
36	
