51	        String releaser = Inputs.requireText(actor, "X-Actor-Id");
52	        if (keys == null || keys.isEmpty() || keys.size() > MAX_BATCH_SIZE) {
53	            throw ApiException.badRequest("批量放行条数必须为 1～" + MAX_BATCH_SIZE);
54	        }
55	        List<String> orderedKeys = keys.stream().map(k -> Inputs.requireText(k, "keys[]")).toList();
56	        Set<String> distinct = new HashSet<>(orderedKeys);
57	        if (distinct.size() != orderedKeys.size()) {
58	            throw ApiException.badRequest("批量放行包含重复测量键");
59	        }
60	
61	        List<ItemFailure> failures = new ArrayList<>();
62	        List<Measurement> approved = new ArrayList<>();
63	        for (String key : orderedKeys.stream().sorted().toList()) {
64	            var locked = measurements.findByKeyForUpdate(key);
65	            if (locked.isEmpty()) {
66	                failures.add(new ItemFailure(key, List.of("MEASUREMENT_NOT_FOUND")));
67	                continue;
68	            }
