70	            List<String> reasons = new ArrayList<>();
71	            if (measurement.status() == MeasurementStatus.RELEASED) {
72	                reasons.add("ALREADY_RELEASED");
73	            } else if (measurement.status() != MeasurementStatus.PENDING) {
74	                reasons.add("NOT_PENDING");
75	            }
76	            if (!measurement.passed()) {
77	                reasons.add("NOT_PASSED");
78	            }
