import java.time.Instant;
import java.util.List;

/**
 * 联合批次放行成功响应。released 按测量键字典序输出，保证同键重放时响应快照一致。
 *
 * @param jointBatchKey 联合批次键
 * @param releasedBy    放行人（X-Actor-Id）
 * @param releasedAt    放行时间（UTC）
 * @param released      已放行的测量键（字典序）
 */
public record JointReleaseResponse(String jointBatchKey, String releasedBy, Instant releasedAt,
                                   List<String> released) {
}

package com.example.starter.calibration.api.dto;

/**
 * 联合放行批次明细响应项：放行时固化的测量标识、证书与未舍入计算值快照。
 *
 * @param measurementId 测量记录 ID
 * @param measurementKey 测量键快照
 * @param certificateId 放行时使用的校准证书 ID 快照
 * @param computedValue 放行时未舍入计算值快照（去尾零十进制字符串）
 */
public record JointReleaseItemResponse(long measurementId, String measurementKey,
                                       long certificateId, String computedValue) {
}

package com.example.starter.calibration.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 联合放行记录及按批次的测量放行明细查询响应。items 按测量键字典序稳定排序。
 *
 * @param jointBatchKey 联合批次键
 * @param releasedBy    放行人（X-Actor-Id）
 * @param releasedAt    放行时间（UTC）
 * @param items         本批全部测量放行明细（不可变快照）
