package com.example.starter.calibration;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 跨仪器联合批次放行测试：混合仪器原子放行、422 逐条原因与整批回滚、
 * 批次参数校验、jointBatchKey 幂等（同参重放快照/异参 409/失败不占键）、
 * 联合放行记录查询及撤销后记录不可变。
 */
@SpringBootTest
@AutoConfigureMockMvc
class JointReleaseApiTest {

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM joint_release_item");
        jdbc.update("DELETE FROM joint_release_batch");
        jdbc.update("DELETE FROM release_record");
        jdbc.update("DELETE FROM measurement");
        jdbc.update("DELETE FROM calibration_certificate");
        jdbc.update("DELETE FROM instrument_lock");
    }

    private long createCert(String instrument, String a, String b) throws Exception {
        String body = mvc.perform(post("/api/certificates").contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"instrumentId":"%s","validFrom":"2026-01-01T00:00:00Z",
                                 "validTo":"2028-01-01T00:00:00Z","a":"%s","b":"%s"}
                                """.formatted(instrument, a, b)))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        return ((Number) com.jayway.jsonpath.JsonPath.read(body, "$.id")).longValue();
    }

    private void submit(String key, String instrument, String reading, String lower,
                        String upper, String by) throws Exception {
        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"measurementKey":"%s","instrumentId":"%s",
                                 "measuredAt":"2026-06-01T00:00:00Z","reading":"%s",
                                 "lowerLimit":"%s","upperLimit":"%s","submittedBy":"%s"}
                                """.formatted(key, instrument, reading, lower, upper, by)))
                .andExpect(status().isCreated());
    }

    @Test
    void mixedInstrumentBatchReleasedAtomically() throws Exception {
        long certA = createCert("INS-A", "1", "0");
        long certB = createCert("INS-B", "2", "1");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-B", "3", "0", "9", "bob");

        // 换序提交，响应中 released 按字典序稳定输出
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-1\",\"keys\":[\"J-2\",\"J-1\"]}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.jointBatchKey").value("JB-1"))
                .andExpect(jsonPath("$.releasedBy").value("carol"))
                .andExpect(jsonPath("$.releasedAt").isString())
                .andExpect(jsonPath("$.released[0]").value("J-1"))
                .andExpect(jsonPath("$.released[1]").value("J-2"));

        // 每条测量自身放行历史与既有单条查询兼容，批次 ID 即联合批次键
        mvc.perform(get("/api/measurements/{key}", "J-1"))
                .andExpect(jsonPath("$.status").value("RELEASED"))
                .andExpect(jsonPath("$.usable").value(true))
                .andExpect(jsonPath("$.releases[0].batchId").value("JB-1"))
                .andExpect(jsonPath("$.releases[0].releasedBy").value("carol"));
        mvc.perform(get("/api/measurements/{key}", "J-2"))
                .andExpect(jsonPath("$.status").value("RELEASED"))
                .andExpect(jsonPath("$.releases[0].batchId").value("JB-1"));

        // 按联合批次键查询全部关联测量明细：固化证书与计算值快照，稳定排序
        mvc.perform(get("/api/joint-releases/{key}", "JB-1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.jointBatchKey").value("JB-1"))
                .andExpect(jsonPath("$.releasedBy").value("carol"))
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].measurementKey").value("J-1"))
                .andExpect(jsonPath("$.items[0].certificateId").value((int) certA))
                .andExpect(jsonPath("$.items[0].computedValue").value("1"))
                .andExpect(jsonPath("$.items[1].measurementKey").value("J-2"))
                .andExpect(jsonPath("$.items[1].certificateId").value((int) certB))
                .andExpect(jsonPath("$.items[1].computedValue").value("7"));

        mvc.perform(get("/api/measurements/usable")).andExpect(jsonPath("$.length()").value(2));
    }

    @Test
    void invalidBatchRejectsWholeBatchWith422AndItemReasons() throws Exception {
        createCert("INS-A", "1", "0");
        createCert("INS-B", "1", "0");
        submit("J-OK", "INS-A", "1", "0", "9", "alice");   // 合格但提交人=放行人
        submit("J-FAIL", "INS-B", "100", "0", "9", "bob"); // 不合格
        submit("J-GOOD", "INS-A", "2", "0", "9", "bob");   // 合法可放行

        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-2\",\"keys\":[\"J-OK\",\"J-FAIL\",\"J-GOOD\",\"J-MISSING\"]}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("JOINT_BATCH_REJECTED"))
                .andExpect(jsonPath("$.failures[?(@.key=='J-OK')].reasons[0]").value("SAME_ACTOR"))
                .andExpect(jsonPath("$.failures[?(@.key=='J-FAIL')].reasons[0]").value("NOT_PASSED"))
                .andExpect(jsonPath("$.failures[?(@.key=='J-MISSING')].reasons[0]")
                        .value("MEASUREMENT_NOT_FOUND"))
                .andExpect(jsonPath("$.failures.length()").value(3));

        // 整批回滚：J-GOOD 仍为待放行，无任何放行记录与联合批次记录
        mvc.perform(get("/api/measurements/{key}", "J-GOOD"))
                .andExpect(jsonPath("$.status").value("PENDING"));
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM release_record", Integer.class));
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_item", Integer.class));
    }

    @Test
    void revokedCertificateRejectsWholeBatchWith422() throws Exception {
        long certA = createCert("INS-A", "1", "0");
        createCert("INS-B", "1", "0");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-B", "2", "0", "9", "bob");
        mvc.perform(post("/api/certificates/{id}/revoke", certA)).andExpect(status().isOk());

        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-3\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.failures[?(@.key=='J-1')].reasons[0]")
                        .value("CERTIFICATE_REVOKED"));

        mvc.perform(get("/api/measurements/{key}", "J-2"))
                .andExpect(jsonPath("$.status").value("PENDING"));
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));
    }

    @Test
    void batchParameterValidation() throws Exception {
        createCert("INS-A", "1", "0");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-A", "2", "0", "9", "bob");

        // 少于 2 条 → 400
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-4\",\"keys\":[\"J-1\"]}"))
                .andExpect(status().isBadRequest());

        // 超过 20 条 → 400
        String big = java.util.stream.IntStream.range(0, 21)
                .mapToObj(i -> "\"K" + i + "\"").toList().toString();
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-4\",\"keys\":" + big + "}"))
                .andExpect(status().isBadRequest());

        // 批次内重复键 → 400
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-4\",\"keys\":[\"J-1\",\"J-1\"]}"))
                .andExpect(status().isBadRequest());

        // 缺少 jointBatchKey → 400
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isBadRequest());

        // 缺少 X-Actor-Id → 400
        mvc.perform(post("/api/joint-releases")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-4\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isBadRequest());

        // 全部 400 不占键、不放行
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));
        mvc.perform(get("/api/measurements/{key}", "J-1"))
                .andExpect(jsonPath("$.status").value("PENDING"));
    }

    @Test
    void idempotentReplaySameKeySameParamsReturnsSnapshot() throws Exception {
        createCert("INS-A", "1", "0");
        createCert("INS-B", "1", "0");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-B", "2", "0", "9", "bob");

        String first = mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-5\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        String firstReleasedAt = com.jayway.jsonpath.JsonPath.read(first, "$.releasedAt");

        // 同键同参（测量集合换序）重放：返回首次响应快照，不重复放行
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-5\",\"keys\":[\"J-2\",\"J-1\"]}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.releasedAt").value(firstReleasedAt))
                .andExpect(jsonPath("$.released[0]").value("J-1"))
                .andExpect(jsonPath("$.released[1]").value("J-2"));

        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));
        assertEquals(2, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_item", Integer.class));
        assertEquals(2, jdbc.queryForObject("SELECT COUNT(*) FROM release_record", Integer.class));

        // 同键异参（测量集合不同）→ 409
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-5\",\"keys\":[\"J-1\"]}"))
                .andExpect(status().isBadRequest()); // 条数非法先于幂等裁决
        submit("J-3", "INS-A", "3", "0", "9", "alice");
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-5\",\"keys\":[\"J-1\",\"J-3\"]}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("JOINT_BATCH_KEY_CONFLICT"));

        // 同键异参（放行人不同）→ 409
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "dave")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-5\",\"keys\":[\"J-2\",\"J-1\"]}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("JOINT_BATCH_KEY_CONFLICT"));
    }

    @Test
    void failedAttemptDoesNotOccupyKey() throws Exception {
        createCert("INS-A", "1", "0");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-A", "2", "0", "9", "bob");

        // 首次失败（SAME_ACTOR）→ 422，不占键
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-6\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isUnprocessableEntity());
        assertEquals(0, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));

        // 同一 jointBatchKey 修正放行人后成功
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-6\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.jointBatchKey").value("JB-6"));
        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM joint_release_batch", Integer.class));
    }

    @Test
    void jointRecordImmutableAfterCertificateRevoked() throws Exception {
        long certA = createCert("INS-A", "1", "0");
        createCert("INS-B", "1", "0");
        submit("J-1", "INS-A", "1", "0", "9", "alice");
        submit("J-2", "INS-B", "2", "0", "9", "bob");
        mvc.perform(post("/api/joint-releases")
                        .header("X-Actor-Id", "carol")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"jointBatchKey\":\"JB-7\",\"keys\":[\"J-1\",\"J-2\"]}"))
                .andExpect(status().isOk());

        // 放行提交后撤销证书：不追溯改写已完成的联合放行记录
        mvc.perform(post("/api/certificates/{id}/revoke", certA)).andExpect(status().isOk());
        mvc.perform(get("/api/joint-releases/{key}", "JB-7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].measurementKey").value("J-1"))
                .andExpect(jsonPath("$.items[0].certificateId").value((int) certA))
                .andExpect(jsonPath("$.items[0].computedValue").value("1"));

        // 测量历史保留、状态仍为 RELEASED，但失去当前可用资格
        mvc.perform(get("/api/measurements/{key}", "J-1"))
                .andExpect(jsonPath("$.status").value("RELEASED"))
                .andExpect(jsonPath("$.usable").value(false))
                .andExpect(jsonPath("$.releases[0].batchId").value("JB-7"));
        mvc.perform(get("/api/measurements/usable"))
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].measurementKey").value("J-2"));
    }

    @Test
    void detailUnknownJointBatchReturns404() throws Exception {
        mvc.perform(get("/api/joint-releases/{key}", "NO-SUCH-BATCH"))
                .andExpect(status().isNotFound());
    }
}

content.thinking:
Note: `jsonPath("$.items[0].certificateId").value((int) certA)` — cert id is a long; JSON number read as Integer if small. Existing tests use `((Number) JsonPath.read(...)).longValue()`. For jsonPath value matching, certificateId will serialize as number; `.value((int) certA)` should match if the id fits int. Safer: `.value((int) certA)` — ids are small (1,2). OK.

Now the concurrency test. Deterministic lock-based tests need PlatformTransactionManager. Write JointReleaseConcurrencyTest:

```java
@SpringBootTest
@AutoConfigureMockMvc
class JointReleaseConcurrencyTest {
    @Autowired MockMvc mvc;
    @Autowired JdbcTemplate jdbc;
    @Autowired PlatformTransactionManager txManager;

    @BeforeEach clean...

    // helper awaitBlocked(Thread t): poll until WAITING/TIMED_WAITING, timeout 10s
```

Test 1: concurrentSharedMeasurementExactlyOneSucceeds — race, 5 rounds, exactly one 200, loser in {409,422}, invariants; track 409 observed.

Test 2: measurementReleasedBetweenCheckAndCommitYields409 (deterministic):
- setup certs INS-A, INS-B; M-1 (INS-A), M-2 (INS-B)
- TransactionTemplate tx = new TransactionTemplate(txManager);
- CountDownLatch locked = new CountDownLatch(1);
- Start thread T performing joint release [M-1, M-2] actor carol — but it must start AFTER main thread holds the M-1 lock. Main thread: tx.execute(status -> { jdbc.queryForObject("SELECT id FROM measurement WHERE measurement_key='M-1' FOR UPDATE", Long.class); locked.countDown(); awaitBlocked(releaseThread); jdbc.update("UPDATE measurement SET status='RELEASED' WHERE measurement_key='M-1'"); return null; });
- releaseThread: locked.await(); mvc.perform(...) — phase 1 reads M-1 PENDING (T1 hasn't committed update), blocks at phase-2 FOR UPDATE on M-1.
- awaitBlocked polls releaseThread.getState() until WAITING/TIMED_WAITING.
- Then T1 updates and commits → release unblocks, sees RELEASED → 409 CONCURRENT_RELEASE_CONFLICT.
- Assert status 409, code; M-2 PENDING; joint_release_batch count 0; release_record count 0.

Note: the release thread does phase-1 unlocked reads while T1 holds the lock — reads don't block in H2 (READ_COMMITTED, MVCC). Phase-1 passes (M-1 PENDING since T1's update uncommitted). Then phase-2 FOR UPDATE blocks. 

Timing subtlety: release thread might reach phase-2 lock before we check awaitBlocked — that's the point, it blocks there. But could the release thread still be in phase 1 when we check state? awaitBlocked waits until it's WAITING/TIMED_WAITING — during phase 1 it's RUNNABLE briefly. Poll loop handles that. But there's a risk: H2's lock wait — is the thread state WAITING/TIMED_WAITING? H2 uses internal lock with await — typically TIMED_WAITING (it polls with timeout). Yes.

But another subtlety: the release thread's phase-1 reads M-1 — if T1 already executed the UPDATE (uncommitted), the SELECT without lock... In H2 with default MVCC, reading a row locked by another transaction: uncommitted update — read sees old committed value (MVCC). OK. But we only do the UPDATE after awaitBlocked, so phase-1 definitely sees PENDING.

Also the joint release thread inserts joint_release_batch row first (uncommitted) — no conflict with T1.

Deadlock risk: release thread inserted batch row, then waits for M-1 lock; T1 holds M-1 lock, does update, commits. No cycle.

Test 3: certificateRevokedBetweenCheckAndCommitYields409 (deterministic):
- cert INS-A; M-1, M-2 both INS-A.
- T1: SELECT id FROM calibration_certificate WHERE id=? FOR UPDATE; locked.countDown(); awaitBlocked(thread); UPDATE ... SET revoked=TRUE, revoked_at=NOW; commit.
- release thread: joint release [M-1, M-2] → phase 1 ok (cert not revoked yet), phase 2: locks M-1, M-2 (no contention), then findByIdForUpdate(certId) → blocks.
- After T1 commits → sees revoked → 409 CONCURRENT_CERTIFICATE_REVOKED.
- Assert 409, code; M-1, M-2 PENDING; no records.

Wait — revoked_at param: use JdbcTimes? In test just use jdbc.update with java.sql.Timestamp or LocalDateTime.now(). Column DATETIME(6); pass LocalDateTime.now(UTC). Fine.

Test 4: concurrentSameKeySameParamsBothReplaySnapshot:
- certs, M-1, M-2.
- two threads, same jointBatchKey JB-S, keys ["M-1","M-2"] (one thread uses reversed order — same params), actor carol both.
- Both should return 200 with identical releasedAt. Assert both 200, bodies equal (releasedAt equal), joint_release_batch count 1, release_record count 2, joint_release_item count 2.

Race: loser blocks on INSERT unique key until winner commits → DuplicateKeyException → replay → 200. But wait: what if loser's findBatchByKey pre-check runs before winner inserts? Then loser proceeds to insertBatch → blocks → winner commits → DuplicateKeyException → resolveReplay → 200. Good. What if loser starts after winner commits? Pre-check finds row → replay → 200. All paths 200. 

Test 5 (race): revokeAndJointReleaseConcurrentFollowCommitOrder — rounds loop similar to existing:
- each round: cert INS-RR-r, M-1-r, M-2-r; threads: revoke cert vs joint release [M-1-r, M-2-r] JB-R-r.
- revoke → 200; release ∈ {200, 409, 422}.
- If release 200: both measurements RELEASED, joint batch exists, released_at <= revoked_at? Actually release commits before revoke in that case (revoke blocked on cert lock). released_at not after revoked_at. Assert.
- Else: measurements PENDING, no joint batch, no release records.

Hmm wait — if release commits first (200), revoke then proceeds → 200 revoked. If revoke commits first, release sees revoked at phase 1 (422) or phase 2 (409). Both fine.

Also check released_at <= revoked_at using timestamps from DB like existing test.

Now, awaitBlocked helper:

```java
private static void awaitBlocked(Thread thread) throws InterruptedException {
    long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
    while (System.nanoTime() < deadline) {
        Thread.State state = thread.getState();
        if (state == Thread.State.WAITING || state == Thread.State.TIMED_WAITING) {
            return;
        }
        Thread.sleep(20);
    }
    throw new AssertionError("等待释放线程进入锁等待超时");
}
```

Hmm — one concern: the release thread might be WAITING on something else transiently (e.g., Hikari getting connection — waiting on connection pool if none available). Pool size 10, only 2 connections in use. Should be fine.

Another concern: MockMvc perform in the release thread — the thread must be started before T1's lock? Order: start T1 transaction first (in main thread via tx.execute — but tx.execute is synchronous and blocks main thread until complete!). So structure: 

```java
ExecutorService pool = Executors.newSingleThreadExecutor();
CountDownLatch locked = new CountDownLatch(1);
Future<Integer> releaseStatus = pool.submit(() -> {
    locked.await();
    return mvc.perform(post("/api/joint-releases")...).andReturn().getResponse().getStatus();
});
Thread releaseThread = ... // hmm, pool thread not directly accessible
```

I need the Thread object for awaitBlocked. Instead create thread manually:

```java
AtomicInteger releaseStatus = new AtomicInteger(-1);
AtomicReference<String> releaseBody = new AtomicReference<>();
Thread releaseThread = new Thread(() -> {
    try {
        locked.await();
        var result = mvc.perform(post(...)).andReturn();
        releaseStatus.set(result.getResponse().getStatus());
        releaseBody.set(result.getResponse().getContentAsString());
    } catch (Exception e) { throw new RuntimeException(e); }
});
releaseThread.start();
// main: T1 via TransactionTemplate
new TransactionTemplate(txManager).execute(status -> {
    jdbc.queryForObject("SELECT id FROM measurement WHERE measurement_key = ? FOR UPDATE", Long.class, "M-1");
    locked.countDown();
    awaitBlocked(releaseThread);
    jdbc.update("UPDATE measurement SET status = 'RELEASED' WHERE measurement_key = ?", "M-1");
    return null;
});
releaseThread.join(TimeUnit.SECONDS.toMillis(30));
assertEquals(409, releaseStatus.get());
```

Exception in releaseThread: wrap — better capture into AtomicReference<Throwable> and rethrow. Use a FutureTask? Simpler: AtomicReference<Throwable> error; after join, if error != null throw.

Actually cleaner: use ExecutorService + Future, and get the thread state differently... awaitBlocked needs Thread. I can submit a task that stores Thread.currentThread() into an AtomicReference, then poll that thread's state. Let me do:

```java
ExecutorService pool = Executors.newSingleThreadExecutor();
AtomicReference<Thread> workerRef = new AtomicReference<>();
Future<Integer> future = pool.submit(() -> {
    workerRef.set(Thread.currentThread());
    locked.await();
    return mvc.perform(...).andReturn().getResponse().getStatus();
});
// wait until workerRef set
while (workerRef.get() == null) Thread.sleep(10);
```

Then in T1: locked.countDown(); awaitBlocked(workerRef.get()); ...

But workerRef is set before locked.await() — the worker waits on latch (WAITING) — awaitBlocked would return immediately while it's waiting on the latch, not on the DB lock! Must countDown latch first, then wait for blocked — but the worker might still be in latch-wait when we poll. Race: after countDown, worker state may briefly still be WAITING (latch) before transitioning. awaitBlocked could return prematurely, then T1 updates and commits before the worker even reads phase 1 → worker sees RELEASED at phase 1 → 422 instead of 409. Test would fail intermittently.

Fix: awaitBlocked should wait until thread is blocked AND has passed the latch. Add a second latch: worker signals after locked.await() returns... no — signaling "started performing" doesn't mean it's blocked on the DB lock. The poll loop should require the thread to be in WAITING/TIMED_WAITING continuously? Hmm.

Better: use a "proceed" latch: worker counts down `started` latch right before mvc.perform? Still not blocked on lock.

Alternative robust approach: poll thread state until WAITING/TIMED_WAITING, then sleep a small extra (e.g., 100ms) and re-check it's still blocked — since the only indefinite wait after latch countdown is the DB lock. Latch wait ends promptly after countDown. So: countDown latch → wait until state is RUNNABLE-ish first? Simplest robust: after countDown, poll until blocked, then poll again 50ms later to confirm still blocked. The latch wait would have ended by then (worker proceeded and got stuck on DB lock). There's still theoretical flakiness but very small. 

Even more robust: don't use a start latch at all. Sequence:
1. T1 (main thread, TransactionTemplate) acquires FOR UPDATE lock on M-1.
2. Main thread signals `locked`.
3. Worker: awaits locked, then performs request.
4. Main: awaitBlocked(worker) with confirm-recheck.
5. Main: update + commit.

The worker can only block indefinitely on the M-1 row lock (phase 2) — phase 1 reads don't block, batch insert doesn't block. So once it's WAITING/TIMED_WAITING and stays so for a recheck interval, it's on the lock. I'll implement awaitBlocked with a "stable for 3 consecutive checks 30ms apart" requirement. Good enough and deterministic in practice.

